"""T-033: the datapack part of the Iron Ore Mines, written by tools/build/r1_mines.py: function/mines/gen/*. Generated, do not edit. The
hand-written logic: function/mines/*.mcfunction.

Scores (objective le.mn, fake players): #near players near (the yard + 64, the box of the workings; the loop works only then), #t the loop
counter, #df the difficulty (0 peaceful), #gt the game time; the cave-ins N (1..3): #cN 0 standing / 1 down (copy of storage
last_ember:mines caves.cN), #wN loops (5 t) left of the warning (0 none); the dead miners K (1..5): #gK generation, #sK 1 spawned, #dK 1
killed, #kK the game time of the death (back 24000 later, nobody within 48), #mK seconds missing at a loaded point; Bran: #bran 0 resting /
1 awake / 2 dead (copy of storage last_ember:mines bran), #bgen his generation, #bmiss seconds missing; the carts C (1..4): #iC 1 = put once.
Entities: the dead miners (zombie le.mn_dead + le.mn_K, le.mnk = K, le.mng = #gK; le.mnr resting (NoAI), le.mna awake), Bran (zombie
le.mn_bran, le.keep, elite; le.mng = #bgen; le.mnr / le.mna), the carts (minecart le.mn_cart + le.mncC), the props (item_display le.mnprop:
the lunch, the pickaxe on the big collapse, the torch at Bran's crawl), Bran's things on peaceful (item le.mnbi). Vanilla monsters of the
workings: le.mnseen (counted by the cap), le.mnhat (the helmet and the pickaxe given)."""
import json, os

HELMET = '{id:"minecraft:leather_helmet",count:1,components:{"minecraft:dyed_color":3877402}}'      # dark brown
PICKS = ['{id:"minecraft:stone_pickaxe",count:1}', '{id:"minecraft:wooden_pickaxe",count:1}']
BRAN_PICK = ('{id:"minecraft:iron_pickaxe",count:1,components:{"minecraft:custom_name":{text:"Кирка Брана",italic:false},'
             '"minecraft:lore":[{text:"Ученическая. Клеймо Хальварда на обухе.",color:"gray",italic:false}],"minecraft:custom_data":{le_bran_pick:1b},'
             '"minecraft:enchantments":{"minecraft:efficiency":1},"minecraft:damage":125}}')
BRAN_LETTER = ('{id:"minecraft:paper",count:1,components:{"minecraft:custom_name":{text:"Письмо Брана",italic:false},'
               '"minecraft:lore":[{text:"Мастеру Хальварду, в Приют.",color:"gray",italic:false}],"minecraft:custom_data":{le_bran_letter:1b}}}')
LUNCH = {"bread": '{id:"minecraft:bread",count:1}', "bowl": '{id:"minecraft:bowl",count:1}', "mug": '{id:"minecraft:flower_pot",count:1}'}

def box(b): return "x=%d,y=%d,z=%d,dx=%d,dy=%d,dz=%d" % (b[0], b[1], b[2], b[3] - b[0], b[4] - b[1], b[5] - b[2])
def f2(v): return "%.2f" % v

def run(meta):
    import r1_mines as R
    ROOT, DP = R.ROOT, R.DP
    GEN = os.path.join(DP, "function/mines/gen"); os.makedirs(GEN, exist_ok=True)
    for f in os.listdir(GEN):
        if f.endswith(".mcfunction"): os.remove(os.path.join(GEN, f))
    hdr = "# generated by tools/build/r1_mines.py (mines_dp.py): "
    def w(name, lines): open(os.path.join(GEN, name + ".mcfunction"), "w", encoding="utf-8").write("\n".join(lines) + "\n")
    pts = meta["points"]; lv = {int(k): v for k, v in meta["levels"].items()}; Y = lv[0]
    WB = pts["work_box"]; yc = pts["yard_c"]
    NEARW = (WB[0] - 8, WB[1] - 4, WB[2] - 8, WB[3] + 8, WB[4] + 2, WB[5] + 8)
    # ---- near, init, scan (hats + cap)
    w("near", [hdr + "#near = players within 64 of the yard or in the box of the workings (+ 8)",
               "execute store result score #near le.mn if entity @a[x=%s,y=%s,z=%s,distance=..64]" % (f2(yc[0]), f2(yc[1]), f2(yc[2])),
               "execute if score #near le.mn matches 0 store result score #near le.mn if entity @a[%s]" % box(NEARW)])
    zero = ["#t", "#near", "#bran", "#bmiss", "#bgen", "#falls", "#capped"] + ["#%s%d" % (p, cv["n"]) for cv in meta["caves"] for p in "cw"] + \
           ["#%s%d" % (p, k) for k in range(1, len(pts["dead"]) + 1) for p in "gsdmk"] + ["#i%d" % c for c in range(1, len(pts["carts"]) + 1)]
    w("init", [hdr + "the scores from the storage (load); unset scores 0"] + ["scoreboard players add %s le.mn 0" % z for z in zero] +
      ["execute store result score #c%d le.mn run data get storage last_ember:mines caves.c%d" % (cv["n"], cv["n"]) for cv in meta["caves"]] +
      ["execute store result score #bran le.mn run data get storage last_ember:mines bran"])
    w("scan", [hdr + "every 10 ticks (mob_eq/scan, after the elite roll): the vanilla zombies, husks and skeletons new in the workings get a miner's helmet and a pickaxe (drop 0; not the elites: their helmet is the region's); at most 10 vanilla monsters there (new ones beyond go; the dead miners, Bran and the elites do not count)",
               "execute if score #near le.mn matches 0 run return 0",
               "execute as @e[type=#last_ember:mines_miners,%s,tag=le.rolled,tag=!le.mnhat,tag=!le.elite,tag=!le.mn_dead,tag=!le.mn_bran] run function last_ember:mines/hat" % box(WB),
               "execute as @e[type=#last_ember:monsters,%s,tag=!le.mnseen,tag=!le.keep,tag=!le.mn_dead,tag=!le.elite] run function last_ember:mines/gen/cap_one" % box(WB)])
    w("cap_one", [hdr + "as a new monster in the workings: more than 10 vanilla monsters there (those already counted and this one) -> it goes (HQ T-033, 3)",
                  "tag @s add le.mnseen",
                  "execute store result score #cap le.mn if entity @e[type=#last_ember:monsters,%s,tag=le.mnseen,tag=!le.keep,tag=!le.mn_dead,tag=!le.elite]" % box(WB),
                  "execute if score #cap le.mn matches 11.. run scoreboard players add #capped le.mn 1",
                  "execute if score #cap le.mn matches 11.. run tag @s remove le.mnseen",
                  "execute if score #cap le.mn matches 11.. run tp @s ~ -1000 ~"])
    # ---- the cave-ins
    chk = [hdr + "every 5 ticks (players near): a cave-in standing whose sensor is active with a player (not spectator / creative) within 10 of its zone starts its warning; the warnings run; at the end the cave-in falls"]
    for cv in meta["caves"]:
        n = cv["n"]; x1, z1, x2, z2 = cv["rect"]; f = cv["floor"]; s = cv["sensor"]
        Z = (x1, f + 1, z1, x2, f + 3, z2)
        NZ = (x1 - 10, f - 9, z1 - 10, x2 + 10, f + 13, z2 + 10)
        cx, cz = (x1 + x2 + 1) / 2, (z1 + z2 + 1) / 2
        chk.append("execute if score #c%d le.mn matches 0 if score #w%d le.mn matches 0 if block %d %d %d minecraft:sculk_sensor[sculk_sensor_phase=active] if entity @e[type=minecraft:player,gamemode=!spectator,gamemode=!creative,%s] run scoreboard players set #w%d le.mn 9" % (n, n, s[0], s[1], s[2], box(NZ), n))
        chk.append("execute if score #w%d le.mn matches 1.. run function last_ember:mines/gen/warn_%d" % (n, n))
        w("warn_%d" % n, [hdr + "the warning of cave-in %d (2 s): gravel dust from the ceiling, the timbering cracks (all within 24), «Крепь трещит!» to those in the zone; then it falls" % n,
                          "scoreboard players remove #w%d le.mn 1" % n,
                          "execute if score #w%d le.mn matches 0 run return run function last_ember:mines/gen/fall_%d" % (n, n),
                          "particle minecraft:falling_dust{block_state:\"minecraft:gravel\"} %s %d.9 %s %s 0.1 %s 0 24 force" % (f2(cx), f + 3, f2(cz), f2((x2 - x1 + 1) / 3), f2((z2 - z1 + 1) / 3)),
                          "execute if score #w%d le.mn matches 6..8 run playsound minecraft:block.wood.break block @a %s %d %s 1.5 0.6" % (n, f2(cx), f + 3, f2(cz)),
                          "execute if score #w%d le.mn matches 3..5 run playsound minecraft:block.gravel.fall block @a %s %d %s 1.5 0.7" % (n, f2(cx), f + 3, f2(cz)),
                          "execute if score #w%d le.mn matches 1..2 run playsound minecraft:block.stone.break block @a %s %d %s 1.5 0.5" % (n, f2(cx), f + 3, f2(cz)),
                          "execute if score #w%d le.mn matches 3.. run playsound minecraft:block.bamboo_wood.break block @a %s %d %s 1.5 0.5" % (n, f2(cx), f + 3, f2(cz)),
                          "title @a[%s] actionbar {\"text\":\"Крепь трещит!\",\"color\":\"gold\"}" % box((x1 - 1, f, z1 - 1, x2 + 1, f + 4, z2 + 1))])
        e = cv["ends"]
        if cv["axis"] == "x": half = (x1, f, z1 - 1, (x1 + x2) // 2, f + 4, z2 + 1)
        else: half = (x1 - 1, f, z1, x2 + 1, f + 4, (z1 + z2) // 2)
        w("push_%d" % n, [hdr + "as an entity in the zone of cave-in %d: to the free cell just outside the nearer end" % n,
                          "execute if entity @s[%s] run return run tp @s %s %s %s" % (box(half), f2(e[0][0]), f2(e[0][1]), f2(e[0][2])),
                          "tp @s %s %s %s" % (f2(e[1][0]), f2(e[1][1]), f2(e[1][2]))])
        ZP = (x1, f, z1, x2, f + 4, z2)
        w("fall_%d" % n, [hdr + "cave-in %d falls (once a world): the dropped items in the zone go, the template `after`, those inside pushed out to the nearer end (players: up to 2 hearts through trap/shield, slowness 2 s; mobs only pushed)" % n,
                          "kill @e[type=minecraft:item,%s]" % box(ZP),
                          "execute as @e[type=minecraft:player,%s] at @s run function last_ember:mines/caught" % box(ZP),
                          "execute as @e[type=!minecraft:player,type=!minecraft:item_display,type=!minecraft:marker,%s] run function last_ember:mines/gen/push_%d" % (box(ZP), n),
                          "execute as @e[type=minecraft:player,tag=le.mncaught] run function last_ember:mines/gen/push_%d" % n,
                          "tag @a remove le.mncaught",
                          "place template last_ember:mines/cave_%d_after %d %d %d" % (n, cv["origin"][0], cv["origin"][1], cv["origin"][2]),
                          "particle minecraft:block{block_state:\"minecraft:gravel\"} %s %d.5 %s %s 1 %s 0 80 force" % (f2(cx), f + 2, f2(cz), f2((x2 - x1 + 1) / 2), f2((z2 - z1 + 1) / 2)),
                          "playsound minecraft:entity.generic.explode block @a %s %d %s 1.5 0.5" % (f2(cx), f + 2, f2(cz)),
                          "playsound minecraft:block.gravel.break block @a %s %d %s 1.5 0.6" % (f2(cx), f + 2, f2(cz)),
                          "scoreboard players set #c%d le.mn 1" % n,
                          "data modify storage last_ember:mines caves.c%d set value 1" % n,
                          "scoreboard players add #falls le.mn 1"])
        w("restore_%d" % n, [hdr + "admin (mines/reset): cave-in %d standing again (template `before`, its sensor)" % n,
                             "place template last_ember:mines/cave_%d_before %d %d %d" % (n, cv["origin"][0], cv["origin"][1], cv["origin"][2]),
                             "setblock %d %d %d minecraft:sculk_sensor[power=0,sculk_sensor_phase=inactive,waterlogged=false]" % tuple(s),
                             "scoreboard players set #c%d le.mn 0" % n, "scoreboard players set #w%d le.mn 0" % n,
                             "data modify storage last_ember:mines caves.c%d set value 0" % n])
    w("caves", chk)
    w("restore_all", [hdr + "admin"] + ["function last_ember:mines/gen/restore_%d" % cv["n"] for cv in meta["caves"]])
    # ---- the dead miners
    dead = pts["dead"]; K = len(dead)
    pt = [hdr + "every second (players near): the points of the dead miners"]
    gch = [hdr + "as a dead miner: one of an old generation (a double from a chunk loaded late) goes"]
    home = [hdr + "as a dead miner: to his point (by le.mnk)"]
    forget = [hdr + "peaceful: the dead miners vanish (monsters) and are not killed: on easy+ they are on their points at once"]
    for k, (x, y, z, yaw, h) in enumerate(dead, 1):
        pick = PICKS[k % 2]
        w("spawn_%d" % k, [hdr + "the dead miner %d on his point: resting (NoAI), a miner's helmet and a pickaxe (drop 0)" % k,
                           "scoreboard players add #g%d le.mn 1" % k,
                           "execute as @e[type=minecraft:zombie,tag=le.mn_%d] run function last_ember:mines/vanish" % k,
                           ("summon minecraft:zombie %s %d %s {Tags:[\"le.mn_dead\",\"le.mn_%d\",\"le.mnr\",\"le.noelite\",\"le.rolled\",\"le.eq_done\",\"le.mnhat\",\"le.mnnew\"],NoAI:1b,PersistenceRequired:1b,CanPickUpLoot:0b,"
                            "Rotation:[%.1ff,0f],equipment:{head:%s,mainhand:%s},drop_chances:{head:0.0f,mainhand:0.0f}}") % (f2(x), y, f2(z), k, yaw, HELMET, pick),
                           "scoreboard players set @e[type=minecraft:zombie,tag=le.mnnew] le.mnk %d" % k,
                           "scoreboard players operation @e[type=minecraft:zombie,tag=le.mnnew] le.mng = #g%d le.mn" % k,
                           "tag @e[type=minecraft:zombie,tag=le.mnnew] remove le.mnnew",
                           "scoreboard players set #s%d le.mn 1" % k, "scoreboard players set #d%d le.mn 0" % k, "scoreboard players set #m%d le.mn 0" % k])
        w("pt_%d" % k, [hdr + "every second: point %d - alive, missing (3 s at a loaded point: killed), killed (back 20 min of game time later, nobody within 48)" % k,
                        "execute unless loaded %d %d %d run return 0" % (int(x), y, int(z)),
                        "execute store result score #c le.mn if entity @e[type=minecraft:zombie,tag=le.mn_%d]" % k,
                        "execute if score #c le.mn matches 1.. run return run scoreboard players set #m%d le.mn 0" % k,
                        "execute if score #df le.mn matches 0 run return 0",
                        "execute if score #s%d le.mn matches 0 if score #d%d le.mn matches 0 run return run function last_ember:mines/gen/spawn_%d" % (k, k, k),
                        "execute if score #s%d le.mn matches 1 run scoreboard players add #m%d le.mn 1" % (k, k),
                        "execute if score #s%d le.mn matches 1 if score #m%d le.mn matches 3.. run scoreboard players operation #k%d le.mn = #gt le.mn" % (k, k, k),
                        "execute if score #s%d le.mn matches 1 if score #m%d le.mn matches 3.. run scoreboard players set #d%d le.mn 1" % (k, k, k),
                        "execute if score #s%d le.mn matches 1 if score #m%d le.mn matches 3.. run scoreboard players set #s%d le.mn 0" % (k, k, k),
                        "scoreboard players operation #e le.mn = #gt le.mn",
                        "scoreboard players operation #e le.mn -= #k%d le.mn" % k,
                        "execute if score #d%d le.mn matches 1 if score #e le.mn matches 24000.. unless entity @e[type=minecraft:player,gamemode=!spectator,x=%s,y=%d,z=%s,distance=..48] run function last_ember:mines/gen/spawn_%d" % (k, f2(x), y, f2(z), k)])
        pt.append("function last_ember:mines/gen/pt_%d" % k)
        gch.append("execute if score @s le.mnk matches %d unless score @s le.mng = #g%d le.mn run return run function last_ember:mines/vanish" % (k, k))
        w("home_%d" % k, [hdr + "the dead miner %d back on his point" % k, "tp @s %s %d %s %.1f 0" % (f2(x), y, f2(z), yaw)])
        home.append("execute if score @s le.mnk matches %d run function last_ember:mines/gen/home_%d" % (k, k))
        forget += ["scoreboard players set #s%d le.mn 0" % k, "scoreboard players set #d%d le.mn 0" % k]
    w("points", pt); w("genchk", gch); w("home", home); w("forget", forget)
    w("dawn_all", [hdr + "admin (mines/reset): every dead miner on his point now"] + ["function last_ember:mines/gen/spawn_%d" % k for k in range(1, K + 1)])
    # ---- Bran
    bx, by, bz, byaw = pts["bran"]
    pk = meta["pocket"]
    LEASH = (pk[0] - 1, pk[1] - 1, pk[2] - 1, pk[3] + 1, pk[4] + 1, pk[5] + 13)
    w("bran_spawn", [hdr + "Bran in his pocket: resting (NoAI), facing the vein, an elite (T-014) named «Бран», the miner's helmet, «Кирка Брана» in his hand (drop 0), his death table last_ember:mines/bran (the pickaxe and the letter always; the elite's trophy when a player killed him)",
                     "scoreboard players add #bgen le.mn 1",
                     "execute as @e[type=minecraft:zombie,tag=le.mn_bran] run function last_ember:mines/vanish",
                     ("summon minecraft:zombie %s %d %s {Tags:[\"le.mn_bran\",\"le.mnr\",\"le.keep\",\"le.noelite\",\"le.eq_done\",\"le.mnhat\",\"le.mnnew\"],NoAI:1b,PersistenceRequired:1b,CanPickUpLoot:0b,"
                      "Rotation:[%.1ff,0f]}") % (f2(bx), by, f2(bz), byaw),
                     "execute as @e[type=minecraft:zombie,tag=le.mnnew] at @s run function last_ember:elite/make",
                     "execute as @e[type=minecraft:zombie,tag=le.mnnew] run function last_ember:mines/gen/bran_dress",
                     "scoreboard players operation @e[type=minecraft:zombie,tag=le.mnnew] le.mng = #bgen le.mn",
                     "tag @e[type=minecraft:zombie,tag=le.mnnew] remove le.mnnew",
                     "scoreboard players set #bmiss le.mn 0"])
    w("bran_dress", [hdr + "as Bran just made an elite: his name, the helmet, his pickaxe, his death table",
                     "data modify entity @s CustomName set value {\"text\":\"Бран\",\"color\":\"gold\"}",
                     "data modify entity @s CustomNameVisible set value 0b",   # T-034: hidden while he rests (it shows through the rock)
                     "item replace entity @s armor.head with minecraft:leather_helmet[dyed_color=3877402]",
                     "item replace entity @s weapon.mainhand with " + "minecraft:iron_pickaxe[custom_name={text:\"Кирка Брана\",italic:false},lore=[{text:\"Ученическая. Клеймо Хальварда на обухе.\",color:\"gray\",italic:false}],custom_data={le_bran_pick:1b},enchantments={\"minecraft:efficiency\":1},damage=125]",
                     "data merge entity @s {drop_chances:{head:0.0f,mainhand:0.0f}}",
                     "data modify entity @s DeathLootTable set value \"last_ember:mines/bran\""])
    w("bran_home", [hdr + "as Bran: to his point", "tp @s %s %d %s %.1f 0" % (f2(bx), by, f2(bz), byaw)])
    w("bran_check", [hdr + "every second (players near, the pocket loaded): Bran (resting or awake): missing 2 s while resting -> again; missing 2 s awake -> dead (once a world); out of his leash (the pocket and 12 of the drift) -> back to his point",
                     "execute unless loaded %d %d %d run return 0" % (int(bx), by, int(bz)),
                     "execute if score #bran le.mn matches 2 run return 0",
                     "execute as @e[type=minecraft:zombie,tag=le.mn_bran] unless score @s le.mng = #bgen le.mn run function last_ember:mines/vanish",
                     "execute store result score #c le.mn if entity @e[type=minecraft:zombie,tag=le.mn_bran]",
                     "execute if score #c le.mn matches 1.. run scoreboard players set #bmiss le.mn 0",
                     "execute if score #c le.mn matches 0 run scoreboard players add #bmiss le.mn 1",
                     "execute if score #bmiss le.mn matches 2.. if score #bran le.mn matches 1 run return run function last_ember:mines/bran_dead",
                     "execute if score #bmiss le.mn matches 2.. if score #bran le.mn matches 0 run function last_ember:mines/gen/bran_spawn",
                     "execute as @e[type=minecraft:zombie,tag=le.mn_bran,tag=le.mna] unless entity @s[%s] run function last_ember:mines/gen/bran_home" % box(LEASH)])
    w("bran_peace", [hdr + "peaceful: Bran is not there; his pickaxe and his letter lie in the pocket (Age -32768: they stay), once (bran 2)",
                     "execute unless loaded %d %d %d run return 0" % (int(bx), by, int(bz)),
                     "execute as @e[type=minecraft:zombie,tag=le.mn_bran] run function last_ember:mines/vanish",
                     "summon minecraft:item %s %d.10 %s {Tags:[\"le.mnbi\"],Age:-32768s,PickupDelay:10s,Motion:[0.0d,0.0d,0.0d],Item:%s}" % (f2(bx), by, f2(bz), BRAN_PICK),
                     "summon minecraft:item %s %d.10 %s {Tags:[\"le.mnbi\"],Age:-32768s,PickupDelay:10s,Motion:[0.0d,0.0d,0.0d],Item:%s}" % (f2(bx + 0.6), by, f2(bz + 0.3), BRAN_LETTER),
                     "scoreboard players set #bran le.mn 2", "data modify storage last_ember:mines bran set value 2"])
    # ---- the carts
    carts = pts["carts"]
    cl = [hdr + "every second: a cart that is not at its place (missing or moved more than 2) while nobody is within 32 comes back; a double (from a chunk loaded late) goes when nobody rides it; the first time it is put at once"]
    for c, (x, y, z) in enumerate(carts, 1):
        cl.append("execute if loaded %d %d %d positioned %s %s %s unless entity @e[type=minecraft:minecart,tag=le.mnc%d,distance=..2] unless entity @a[distance=..32,gamemode=!spectator] run function last_ember:mines/gen/cart_%d" % (int(x), int(y), int(z), f2(x), f2(y), f2(z), c, c))
        cl.append("execute if loaded %d %d %d if score #i%d le.mn matches 0 run function last_ember:mines/gen/cart_%d" % (int(x), int(y), int(z), c, c))
        cl.append("execute store result score #c le.mn if entity @e[type=minecraft:minecart,tag=le.mnc%d]" % c)
        cl.append("execute if score #c le.mn matches 2.. positioned %s %s %s as @e[type=minecraft:minecart,tag=le.mnc%d,sort=nearest,limit=1] run tag @s add le.mnone" % (f2(x), f2(y), f2(z), c))
        cl.append("execute if score #c le.mn matches 2.. as @e[type=minecraft:minecart,tag=le.mnc%d,tag=!le.mnone] unless data entity @s Passengers run kill @s" % c)
        cl.append("tag @e[type=minecraft:minecart,tag=le.mnone] remove le.mnone")
        w("cart_%d" % c, [hdr + "the cart %d back at its place" % c,
                          "execute as @e[type=minecraft:minecart,tag=le.mnc%d] unless data entity @s Passengers run kill @s" % c,
                          "execute if entity @e[type=minecraft:minecart,tag=le.mnc%d] run return 0" % c,
                          "summon minecraft:minecart %s %s %s {Tags:[\"le.mn_cart\",\"le.mnc%d\"],Rotation:[90f,0f]}" % (f2(x), f2(y), f2(z), c),
                          "scoreboard players set #i%d le.mn 1" % c])
    w("carts", cl)
    # ---- the props (the lunch, the pickaxe on the big collapse, the torch at the crawl)
    t = meta["office"]["table"]
    props = []
    for (x, y, z, kind, rot) in pts["lunch"]:
        it = LUNCH["mug" if kind == "decorated_pot" else kind]
        sc = 0.45 if kind == "bread" else 0.4
        if kind == "bread": tr = "left_rotation:[0.7071f,0f,0f,0.7071f],right_rotation:[0f,0f,0f,1f],translation:[0f,0.03f,0f],scale:[%.2ff,%.2ff,%.2ff]" % (sc, sc, sc)
        else: tr = "left_rotation:[0f,0f,0f,1f],right_rotation:[0f,0f,0f,1f],translation:[0f,0.14f,0f],scale:[%.2ff,%.2ff,%.2ff]" % (sc, sc, sc)
        props.append("summon minecraft:item_display %s %s %s {Tags:[\"le.mnprop\"],item:%s,item_display:\"fixed\",Rotation:[%d.0f,0f],transformation:{%s}}" % (f2(x), f2(y + 0.02), f2(z), it, rot, tr))
    px, py, pz = pts["pick"]
    props.append("summon minecraft:item_display %s %s %s {Tags:[\"le.mnprop\"],item:{id:\"minecraft:stone_pickaxe\",count:1},item_display:\"fixed\",Rotation:[200.0f,0f],transformation:{left_rotation:[0f,0f,0.3827f,0.9239f],right_rotation:[0.2588f,0f,0f,0.9659f],translation:[0f,0f,0f],scale:[0.9f,0.9f,0.9f]}}" % (f2(px), f2(py), f2(pz)))
    tx_, ty, tz = pts["torch"]
    props.append("summon minecraft:item_display %s %s %s {Tags:[\"le.mnprop\"],item:{id:\"minecraft:torch\",count:1},item_display:\"fixed\",Rotation:[70.0f,0f],transformation:{left_rotation:[0.7071f,0f,0f,0.7071f],right_rotation:[0f,0f,0f,1f],translation:[0f,0.03f,0f],scale:[0.75f,0.75f,0.75f]}}" % (f2(tx_), f2(ty), f2(tz)))
    w("props_put", [hdr + "the props (missing or doubled: all again): the lunch on the office's table, the pickaxe on the big collapse, the dead torch at Bran's crawl",
                    "kill @e[type=minecraft:item_display,tag=le.mnprop]"] + props)
    w("props_check", [hdr + "every second (players near): the props are there (%d) when the office and the big collapse are loaded" % len(props),
                      "execute unless loaded %d %d %d run return 0" % (t[0], t[1], t[2]),
                      "execute unless loaded %d %d %d run return 0" % (int(px), int(py), int(pz)),
                      "execute store result score #c le.mn if entity @e[type=minecraft:item_display,tag=le.mnprop]",
                      "execute unless score #c le.mn matches %d run function last_ember:mines/gen/props_put" % len(props)])
    w("barrels", [hdr + "admin (mines/reset): the barrels and the chest again with their loot (their contents are not dropped: air first)"] +
      [l for b_ in meta["barrels"] for l in ("data remove block %d %d %d Items" % tuple(b_["pos"]), "setblock %d %d %d minecraft:air replace" % tuple(b_["pos"]),
       "setblock %d %d %d minecraft:barrel[facing=up,open=false]%s" % (b_["pos"][0], b_["pos"][1], b_["pos"][2], '{LootTable:"%s"}' % b_["loot"] if b_["loot"] else ""))] +
      ["data remove block %d %d %d Items" % tuple(meta["office"]["chest"]), "setblock %d %d %d minecraft:air replace" % tuple(meta["office"]["chest"]),
       'setblock %d %d %d minecraft:chest[facing=south,type=single,waterlogged=false]{LootTable:"last_ember:chests/r1/miner"}' % tuple(meta["office"]["chest"])])
    # ---- admin teleports
    tps = {"yard": (yc[0], Y + 1, yc[2] + 8), "office": (259.5, Y + 1, -73.5), "h1": (299.5, lv[1] + 1, -60.5), "h2": (283.5, lv[2] + 1, -59.5),
           "h3": (289.5, lv[3] + 1, -44.5), "big": (264.5, lv[3] + 1, -59.5), "pocket": (264.5, lv[3] + 1, -72.5), "shaft": (274.5, lv[3] + 1, -71.5)}
    for k, (x, y, z) in tps.items(): w("tp_" + k, [hdr + "admin", "tp @s %s %s %s" % (f2(x), f2(y), f2(z))])
    # tags
    tagp = os.path.join(DP, "tags/entity_type/mines_miners.json")
    json.dump({"values": ["minecraft:zombie", "minecraft:husk", "minecraft:skeleton"]}, open(tagp, "w"), indent=1)
